    ~Work() { try { r.syncStream(); } catch (...) { std::terminate(); } }
    rt::Tensor alloc(rt::Shape shape, rt::DataType type) {
        auto x = rt::Tensor::empty(r, shape, type); held.push_back(x); return x;
    }
    rt::Tensor ids(const std::vector<int64_t> &host) {
