            c4_tile_r5920::policy.load(std::memory_order_acquire)==16&&wide_r3443::selected(r)==5&&
            requests.size()==tokens&&std::all_of(requests.begin(),requests.end(),[](const auto&q){return q.tokens==1&&q.past>0;});
        if(tiled){
